  static std::atomic<uint64_t> s_reflexFrameId{1};
  uint64_t D3D11Rtx::GetReflexFrameId() { return s_reflexFrameId.load(); }
  void D3D11Rtx::IncrementReflexFrameId() { s_reflexFrameId.fetch_add(1); }


